App.pluginsLoaded={};App.embedModePluginsCount=0;
App.loadRoadmapPlugin = function(pluginId)
{
	var roadmapBase = PLUGINS_BASE_PATH === '.' ? './' : PLUGINS_BASE_PATH; // NEW: desktop dependency URLs share the stored-plugin canonical path.
	if (pluginId === 'gardenRoadmaps' && !App.roadmapManagerRequested) { App.roadmapManagerRequested = true; App.embedModePluginsCount++; App.pluginsLoaded[roadmapBase + App.pluginRegistry.gardenRoadmaps] = true; } // CHANGE: reserve the stored Manager path while its pure dependencies load.
	App.roadmapScriptLoads = App.roadmapScriptLoads || {}; // NEW
	function load(path, complete)
	{
		var url = roadmapBase + path; // CHANGE
		var entry = App.roadmapScriptLoads[url]; // NEW
		if (entry != null) { if (entry.done) complete(); else entry.waiters.push(complete); return; } // NEW
		entry = {done: false, waiters: [complete]}; // NEW
		App.roadmapScriptLoads[url] = entry; // NEW
		App.pluginsLoaded[url] = true; // NEW: also deduplicate the stored-path loading branch.
		mxscript((typeof window.drawDevUrl === 'undefined' ? '' : window.drawDevUrl) + url, function()
		{
			entry.done = true; var waiters = entry.waiters.splice(0); // NEW
			waiters.forEach(function(callback) { callback(); }); // NEW
		}, null, null, true, function(message)
		{
			delete App.roadmapScriptLoads[url]; delete App.pluginsLoaded[url]; // NEW: a later request may retry.
			entry.waiters.length = 0; // NEW: never initialize Manager without its dependencies.
			if (App.roadmapManagerRequested && !App.roadmapManagerLoaded) { App.roadmapManagerRequested = false; App.embedModePluginsCount--; delete App.pluginsLoaded[roadmapBase + App.pluginRegistry.gardenRoadmaps]; } // CHANGE
			if (window.console) console.error('Roadmap dependency unavailable:', message); // NEW
		}); // NEW
	}
	load(App.pluginRegistry.gardenRoadmapCore, function()
	{
		if (pluginId !== 'gardenRoadmaps') return; // NEW
		load(App.pluginRegistry.gardenRoadmaps, function() { App.roadmapManagerLoaded = true; }); // CHANGE: Core now registers native roadmap rendering.
	}); // NEW
}; // NEW

/**
 * Queue for loading plugins and wait for UI instance
 */
App.loadPlugins = function(plugins, useInclude)
{
	EditorUi.debug('Loading plugins', plugins);

	for (var i = 0; i < plugins.length; i++)
	{
		if (plugins[i] != null && plugins[i].length > 0)
		{
			try
			{
				if (plugins[i] === 'gardenRoadmapCore' || plugins[i] === 'gardenRoadmaps') { App.loadRoadmapPlugin(plugins[i]); continue; } // NEW
				if (App.pluginRegistry[plugins[i]] != null)
				{
					var url = PLUGINS_BASE_PATH + App.pluginRegistry[plugins[i]];

					if (App.pluginsLoaded[url] == null)
					{
						App.pluginsLoaded[url] = true;
						App.embedModePluginsCount++;

						if (typeof window.drawDevUrl === 'undefined')
						{
							if (useInclude)
							{
								mxinclude(url);
							}
							else
							{
								mxscript(url);
							}
						}
						else
						{
							if (useInclude)
							{
								mxinclude(url);
							}
							else
							{
								mxscript(drawDevUrl + url);
							}
						}
					}
				}
				else if (window.console != null)
				{
					console.log('Unknown plugin:', plugins[i]);
				}
			}
			catch (e)
			{
				if (window.console != null)
				{
					console.log('Error loading plugin:', plugins[i], e);
				}
			}
		}
	}
}
